#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-22

# Does paired-probe.sh actually catch the four probes that fooled me today?
# Each case replays the real shape. Expected exit: 1 = BLIND (caught), 0 = ok.
set -uo pipefail
PP="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"/src/skills/paired-probe/scripts/paired-probe.sh
SP="${TMPDIR:-/tmp}"
W="$SP/pp-fixtures"; rm -rf "$W"; mkdir -p "$W"

pass=0; fail=0
expect() { # $1=expected rc  $2=actual rc  $3=label
  if [ "$1" = "$2" ]; then echo "   [ok]   $3"; pass=$((pass+1));
  else echo "   [FAIL] $3 (expected rc=$1 got rc=$2)"; fail=$((fail+1)); fi
}

echo "== case 1: the local-ref probe (says 'absent' for a pushed branch)"
# a check that always prints nothing, regardless of the real answer
bash "$PP" --name "branch pushed? (via a cache that is always empty)" \
  --present "grep -x 'feat/real' $W/empty-cache 2>/dev/null" \
  --absent  "grep -x 'feat/fake' $W/empty-cache 2>/dev/null" >/dev/null 2>&1
expect 1 $? "BLIND: identical empty output both ways"

echo
echo "== case 2: a probe that DOES discriminate (the fixed version)"
printf 'feat/real\n' > "$W/remote-truth"
bash "$PP" --name "branch pushed? (asking the remote list)" \
  --present "grep -x 'feat/real' $W/remote-truth" \
  --absent  "grep -x 'feat/fake' $W/remote-truth" >/dev/null 2>&1
expect 0 $? "DISCRIMINATES: found vs not-found differ"

echo
echo "== case 3: the swallowed-write sweep (measured zero, printed safe)"
bash "$PP" --name "worktrees examined" \
  --measure "cat $W/blocked-output 2>/dev/null || true" --min-count 1 >/dev/null 2>&1
expect 1 $? "BLIND: zero items must not read as clean"

echo
echo "== case 4: same sweep, when it really did measure"
printf 'wt-a\nwt-b\nwt-c\n' > "$W/real-output"
bash "$PP" --name "worktrees examined" \
  --measure "cat $W/real-output" --min-count 1 >/dev/null 2>&1
expect 0 $? "MEASURED: 3 items"

echo
echo "== case 5: the probe itself dies (could-not-observe, not a verdict)"
bash "$PP" --name "unreadable path" \
  --measure "cat $W/does-not-exist" --min-count 1 >/dev/null 2>&1
expect 3 $? "COULD-NOT-OBSERVE: rc=3, distinct from both verdicts"

echo
echo "== case 6: usage error is its own code"
bash "$PP" --name "no arms given" >/dev/null 2>&1
expect 2 $? "usage rc=2"

echo
echo "Results: $pass passed, $fail failed"
[ "$fail" = "0" ] || exit 1
